{
  "meta": {
    "name": "SuperApp",
    "description": "A single application integrating social networking, a marketplace, online banking, ride-sharing, video streaming, and a dating service."
  },
  "entities": [
    {
      "name": "Post",
      "ownable": true,
      "fields": [
        {
          "name": "content",
          "type": "text",
          "required": true
        },
        {
          "name": "timestamp",
          "type": "datetime",
          "required": true
        },
        {
          "name": "likes",
          "type": "integer",
          "default": 0
        },
        {
          "name": "comments",
          "type": "text"
        }
      ]
    },
    {
      "name": "Product",
      "ownable": true,
      "fields": [
        {
          "name": "name",
          "type": "string",
          "required": true
        },
        {
          "name": "description",
          "type": "text"
        },
        {
          "name": "price",
          "type": "number",
          "required": true
        },
        {
          "name": "imageUrl",
          "type": "url"
        }
      ]
    },
    {
      "name": "Order",
      "ownable": true,
      "fields": [
        {
          "name": "orderDate",
          "type": "datetime",
          "required": true
        },
        {
          "name": "status",
          "type": "enum",
          "required": true,
          "enumValues": [
            "pending",
            "processing",
            "shipped",
            "delivered",
            "cancelled"
          ],
          "default": "pending"
        }
      ],
      "relations": [
        {
          "name": "product",
          "kind": "manyToOne",
          "target": "Product",
          "required": true
        }
      ]
    },
    {
      "name": "Ride",
      "ownable": true,
      "fields": [
        {
          "name": "pickupLocation",
          "type": "string",
          "required": true
        },
        {
          "name": "dropoffLocation",
          "type": "string",
          "required": true
        },
        {
          "name": "fare",
          "type": "number",
          "required": true
        },
        {
          "name": "status",
          "type": "enum",
          "required": true,
          "enumValues": [
            "requested",
            "accepted",
            "in_progress",
            "completed",
            "cancelled"
          ],
          "default": "requested"
        }
      ]
    },
    {
      "name": "Video",
      "ownable": true,
      "fields": [
        {
          "name": "title",
          "type": "string",
          "required": true
        },
        {
          "name": "description",
          "type": "text"
        },
        {
          "name": "url",
          "type": "url",
          "required": true
        },
        {
          "name": "views",
          "type": "integer",
          "default": 0
        }
      ]
    },
    {
      "name": "DatingProfile",
      "ownable": true,
      "fields": [
        {
          "name": "bio",
          "type": "text"
        },
        {
          "name": "interests",
          "type": "string"
        },
        {
          "name": "photos",
          "type": "url"
        }
      ]
    },
    {
      "name": "Account",
      "fields": [
        {
          "name": "accountBalance",
          "type": "number",
          "required": true,
          "default": 0
        }
      ]
    },
    {
      "name": "PaymentMethod",
      "ownable": true,
      "fields": [
        {
          "name": "type",
          "type": "enum",
          "required": true,
          "enumValues": ["credit_card", "debit_card", "bank_account"]
        },
        {
          "name": "details",
          "type": "string",
          "required": true
        }
      ]
    }
  ],
  "roles": [
    {
      "name": "user",
      "isDefault": true
    },
    {
      "name": "admin"
    },
    {
      "name": "seller"
    },
    {
      "name": "driver"
    }
  ],
  "permissions": [
    {
      "role": "user",
      "entity": "Post",
      "actions": [
        "create",
        "read",
        "update",
        "delete"
      ],
      "scope": "own"
    },
    {
      "role": "user",
      "entity": "Product",
      "actions": [
        "read"
      ],
      "scope": "all"
    },
    {
      "role": "seller",
      "entity": "Product",
      "actions": [
        "create",
        "read",
        "update",
        "delete"
      ],
      "scope": "own"
    },
    {
      "role": "user",
      "entity": "Order",
      "actions": [
        "create",
        "read",
        "update"
      ],
      "scope": "own"
    },
    {
      "role": "seller",
      "entity": "Order",
      "actions": [
        "read",
        "update"
      ],
      "scope": "all"
    },
    {
      "role": "user",
      "entity": "Ride",
      "actions": [
        "create",
        "read",
        "update"
      ],
      "scope": "own"
    },
    {
      "role": "driver",
      "entity": "Ride",
      "actions": [
        "read",
        "update"
      ],
      "scope": "all"
    },
    {
      "role": "user",
      "entity": "Video",
      "actions": [
        "read"
      ],
      "scope": "all"
    },
    {
      "role": "user",
      "entity": "DatingProfile",
      "actions": [
        "create",
        "read",
        "update"
      ],
      "scope": "own"
    },
    {
      "role": "user",
      "entity": "Account",
      "actions": [
        "read",
        "update"
      ],
      "scope": "own"
    },
    {
      "role": "user",
      "entity": "PaymentMethod",
      "actions": [
        "create",
        "read",
        "delete"
      ],
      "scope": "own"
    },
    {
      "role": "admin",
      "entity": "Post",
      "actions": [
        "create",
        "read",
        "update",
        "delete"
      ],
      "scope": "all"
    },
    {
      "role": "admin",
      "entity": "Product",
      "actions": [
        "create",
        "read",
        "update",
        "delete"
      ],
      "scope": "all"
    },
    {
      "role": "admin",
      "entity": "Order",
      "actions": [
        "read",
        "update",
        "delete"
      ],
      "scope": "all"
    },
    {
      "role": "admin",
      "entity": "Ride",
      "actions": [
        "read",
        "update",
        "delete"
      ],
      "scope": "all"
    },
    {
      "role": "admin",
      "entity": "Video",
      "actions": [
        "create",
        "read",
        "update",
        "delete"
      ],
      "scope": "all"
    },
    {
      "role": "admin",
      "entity": "DatingProfile",
      "actions": [
        "read",
        "update",
        "delete"
      ],
      "scope": "all"
    },
    {
      "role": "admin",
      "entity": "Account",
      "actions": [
        "read",
        "update"
      ],
      "scope": "all"
    },
    {
      "role": "admin",
      "entity": "PaymentMethod",
      "actions": [
        "read",
        "delete"
      ],
      "scope": "all"
    }
  ],
  "pages": [
    {
      "name": "Social Feed",
      "route": "/feed",
      "type": "list",
      "entity": "Post",
      "access": [
        "user",
        "admin"
      ]
    },
    {
      "name": "Marketplace",
      "route": "/marketplace",
      "type": "list",
      "entity": "Product",
      "access": [
        "user",
        "seller",
        "admin"
      ]
    },
    {
      "name": "My Orders",
      "route": "/my-orders",
      "type": "list",
      "entity": "Order",
      "access": [
        "user",
        "admin"
      ]
    },
    {
      "name": "My Rides",
      "route": "/my-rides",
      "type": "list",
      "entity": "Ride",
      "access": [
        "user",
        "driver",
        "admin"
      ]
    },
    {
      "name": "Video Library",
      "route": "/videos",
      "type": "list",
      "entity": "Video",
      "access": [
        "user",
        "admin"
      ]
    },
    {
      "name": "Dating Profiles",
      "route": "/dating",
      "type": "list",
      "entity": "DatingProfile",
      "access": [
        "user",
        "admin"
      ]
    },
    {
      "name": "Online Banking",
      "route": "/banking",
      "type": "dashboard",
      "access": [
        "user",
        "admin"
      ],
      "widgets": [
        {
          "type": "stat",
          "label": "Account Balance",
          "entity": "Account",
          "metric": "sum",
          "field": "accountBalance"
        }
      ]
    }
  ],
  "plans": [
    {
      "name": "free",
      "isDefault": true
    },
    {
      "name": "premium",
      "price": 10,
      "interval": "month",
      "features": [
        "advanced_analytics",
        "priority_support"
      ]
    }
  ],
  "businessRules": [
    {
      "type": "ownership",
      "id": "postOwnership",
      "entity": "Post"
    },
    {
      "type": "ownership",
      "id": "productOwnership",
      "entity": "Product"
    },
    {
      "type": "ownership",
      "id": "orderOwnership",
      "entity": "Order"
    },
    {
      "type": "ownership",
      "id": "rideOwnership",
      "entity": "Ride"
    },
    {
      "type": "ownership",
      "id": "videoOwnership",
      "entity": "Video"
    },
    {
      "type": "ownership",
      "id": "datingProfileOwnership",
      "entity": "DatingProfile"
    },
    {
      "type": "ownership",
      "id": "paymentMethodOwnership",
      "entity": "PaymentMethod"
    },
    {
      "type": "plan_gate",
      "id": "premiumBankingFeatures",
      "requiresPlan": "premium",
      "gates": {
        "features": [
          "advanced_analytics",
          "priority_support"
        ]
      }
    }
  ],
  "auth": {
    "strategy": "email_password",
    "requireAuth": true
  }
}
